    if (top3.length > 0) {
      return (
        <div ref={ref} className="mx-auto max-w-2xl">
          <div className="flex items-end justify-center gap-1.5 sm:gap-5">
            {top3.map((entry, i) => (
              <div key={entry.team.id} className="w-full min-w-0 max-w-[33%] sm:max-w-[200px]">
                <GlassPillar
