                  delay={i * 0.12}
                  isInView={isInView}
                />
              </div>
            ))}
          </div>
          <div className="mx-auto mt-0 h-[2px] max-w-lg bg-gradient-to-r from-transparent via-ci-jasmine/20 to-transparent" />
        </div>
      );
    }
